// Lee el plan completo (texto del plan de pruebas) y lo divide por escenarios.
function getPlanText(item) {
  if (item.json?.planText) return String(item.json.planText);
  if (item.binary?.file?.data) {
    const buf = Buffer.from(item.binary.file.data, 'base64');
    return buf.toString('utf8');
  }
  throw new Error('No se encontró el plan en json.planText ni en binary.file');
}

const text = getPlanText(items[0]);

// Nombre del sitio: "# Plan de Pruebas – Demoblaze"
const siteMatch = text.match(/^#\s*Plan de Pruebas\s*[–-]\s*(.+)$/m);
const siteName = siteMatch ? siteMatch[1].trim() : 'Demoblaze';

// Captura bloques de "### Escenario X: Título"
const regex = /^###\s*Escenario\s+(\d+)\s*:\s*(.+?)\s*\r?\n([\s\S]*?)(?=^###\s*Escenario\s+\d+\s*:|\Z)/gm;

const out = [];
let m, counter = 0;
while ((m = regex.exec(text)) !== null) {
  counter += 1;                               // <— numeración SECUENCIAL y estable
  const headingIndex = Number(m[1]);          // (por si te sirve tener el original)
  const scenarioName  = m[2].trim();
  const scenarioMd    = m[3].trim();

  out.push({
    json: {
      siteName,
      scenarioIndex: counter,                 // <— usamos la secuencia, no el título
      headingIndex,                           // (opcional) el número que venía en el MD
      scenarioName,
      scenarioMd,
      context: text,
    },
  });
}

if (!out.length) throw new Error('No se encontraron escenarios con el patrón esperado.');
return out;

// SELLAR METADATOS — fija __idx y __title por ítem (se usarán más adelante)
const j = { ...$json };

const idxFromInput = Number(j.scenarioIndex);
const idxFromLoop  = (typeof $itemIndex === 'number') ? $itemIndex + 1 : undefined;

j.__site  = (j.siteName && String(j.siteName).trim()) || 'Demoblaze';
j.__idx   = Number.isFinite(idxFromInput) && idxFromInput > 0
  ? idxFromInput
  : (Number.isFinite(idxFromLoop) ? idxFromLoop : 1);

j.__title = (j.scenarioName && String(j.scenarioName).trim()) || `Escenario ${j.__idx}`;

// limpia fences si hubiera
if (typeof j.output === 'string') {
  j.output = j.output
    .replace(/^\s*```(?:json|typescript|ts)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

return { json: j };

// n8n Code node — SANITIZADOR POST-GENERADOR MEJORADO
const j = $json;

// === Utilidades ===
const toSlug = (s) =>
  String(s ?? '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/["""'']/g, '')
    .replace(/[^a-z0-9\s-]/g, ' ')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');

const pad2 = (n) => String(Number(n || 1)).padStart(2, '0');

// === Preservar metadatos ===
const metadata = {
  __site: j.__site,
  __idx: j.__idx,
  __title: j.__title,
  scenarioMd: j.scenarioMd,
  siteName: j.siteName,
  scenarioIndex: j.scenarioIndex,
  scenarioName: j.scenarioName,
  context: j.context
};

const site = toSlug(metadata.__site || 'demoblaze');
const idx = pad2(metadata.__idx || 1);
const title = String(metadata.__title || `Escenario ${idx}`).trim();
const defaultName = `${site}.${idx}.${toSlug(title)}.spec.ts`;

// === Extraer output del generador ===
let raw = j;
let fileName = '';
let fileContent = '';

// Intentar parsear JSON si viene como string
if (typeof raw.output === 'string') {
  try {
    // Limpiar posibles backticks o formato markdown
    let cleaned = raw.output
      .replace(/^\s*```(?:json)?\s*/i, '')
      .replace(/\s*```\s*$/i, '')
      .trim();

    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) {
      raw = JSON.parse(match[0]);
    } else {
      // No hay JSON válido, usar el string completo como fileContent
      console.warn(`Escenario ${idx}: No se encontró JSON válido, usando output como código`);
      fileName = defaultName;
      fileContent = cleaned;
    }
  } catch (e) {
    // Error parseando, crear archivo con el error comentado
    console.error(`Escenario ${idx}: Error parseando JSON: ${e.message}`);
    fileName = defaultName;
    fileContent = `import { test, expect } from '@playwright/test';

test.describe('${metadata.__site} – ${title}', () => {
  test('${idx} - ${title}', async ({ page }) => {
    // TODO: El generador falló, implementar manualmente
    // Error: ${e.message}

    await page.goto('https://demoblaze.com', { waitUntil: 'domcontentloaded' });
    await page.waitForSelector('#tbodyid .card', { state: 'visible', timeout: 15000 });
    await expect(page).toHaveURL(/https:\\/\\/demoblaze\\.com\\/?/);

    // Implementar pasos del escenario aquí
    expect(1).toBe(1);
  });
});
`;
  }
}

// Si llegó aquí con raw siendo objeto, extraer campos
if (!fileName && !fileContent) {
  fileName = raw.fileName || raw.filename || '';
  fileContent = raw.fileContent ?? raw.content ?? raw.text ?? raw.code ?? '';
}

// === Validar y normalizar fileName ===
if (!fileName || 
    fileName === 'fallback.spec.ts' || 
    fileName.includes('fallback') || 
    fileName.includes('ejemplo')) {
  fileName = defaultName;
}

fileName = String(fileName).replace(/\.spect\.ts$/i, '.spec.ts');
if (!/\.(ts|tsx|js)$/i.test(fileName)) {
  if (!/\.spec$/i.test(fileName)) fileName += '.spec';
  fileName += '.ts';
}

// === Validar fileContent ===
if (!String(fileContent).trim() || fileContent.length < 50) {
  console.warn(`Escenario ${idx}: fileContent vacío o muy corto, creando placeholder`);
  fileContent = `import { test, expect } from '@playwright/test';

test.describe('${metadata.__site} – ${title}', () => {
  test('${idx} - ${title}', async ({ page }) => {
    // TODO: Implementar escenario
    // Pasos del escenario:
    // ${(metadata.scenarioMd || '').split('\\n').slice(0, 5).join('\\n    // ')}

    await page.goto('https://demoblaze.com', { waitUntil: 'domcontentloaded' });
    await page.waitForSelector('#tbodyid .card', { state: 'visible', timeout: 15000 });
    await expect(page).toHaveURL(/https:\\/\\/demoblaze\\.com\\/?/);

    expect(1).toBe(1);
  });
});
`;
}

// === Devolver todo ===
return {
  ...metadata,
  fileName,
  fileContent
};

// Code Final - MINIMAL - Solo arregla errores críticos de sintaxis
// Modo: "Run Once for Each Item"

const inputData = $input.item.json;

console.log('📦 Item #' + (inputData.__idx || '?'));

// ========================================
// 1. OBTENER OUTPUT
// ========================================

let rawOutput = inputData.output || inputData.text || '';

if (!rawOutput || typeof rawOutput !== 'string') {
  console.log('❌ No hay output');
  return { json: inputData };
}

// ========================================
// 2. PARSEAR JSON
// ========================================

let cleanedOutput = rawOutput
  .replace(/```json\s*/g, '')
  .replace(/```typescript\s*/g, '')
  .replace(/```\s*/g, '')
  .trim();

let parsedData;

try {
  parsedData = JSON.parse(cleanedOutput);
  console.log('✅ JSON parseado');
} catch (e) {
  console.log('❌ Error parseando JSON:', e.message);
  return { json: inputData };
}

if (!parsedData.fileName || !parsedData.fileContent) {
  console.log('❌ JSON incompleto');
  return { json: inputData };
}

let fileName = parsedData.fileName;
let content = parsedData.fileContent;

console.log('✅ Archivo:', fileName);

// ========================================
// 3. FIXES CRÍTICOS DE SINTAXIS
// ========================================

// 3.1 CRÍTICO: Arreglar "const page.locator(...) = ..." y similares
// Estos causan SyntaxError inmediato
content = content.replace(/const\s+page\.(locator|getByRole|getByText|getByLabel|getByPlaceholder|getByAltText|getByTitle)\([^)]+\)\s*=\s*page\.\1\([^;]+\)\s*;?\s*/g, '');

// Cualquier otra variante de const page.X = ...
content = content.replace(/const\s+page\.\w+\([^)]*\)\s*=\s*[^;]+;?\s*/g, '');

// 3.2 CRÍTICO: Código fuera del test
// Buscar await page... que esté ANTES de test('
const lines = content.split('\n');
const fixedLines = [];
let codeBeforeTest = [];
let inDescribe = false;
let inTest = false;

for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  const trimmed = line.trim();

  // Detectar inicio de describe
  if (trimmed.includes('test.describe(')) {
    inDescribe = true;
    fixedLines.push(line);
    continue;
  }

  // Detectar inicio de test
  if (inDescribe && trimmed.includes("test('")) {
    inTest = true;
    fixedLines.push(line);

    // Si hay líneas con await antes del test, insertarlas después de async ({ page }) =>
    if (codeBeforeTest.length > 0) {
      // Buscar la línea con async ({ page }) =>
      let asyncLineIndex = i;
      for (let j = i; j < lines.length && j < i + 5; j++) {
        if (lines[j].includes('async ({ page })')) {
          asyncLineIndex = j;
          break;
        }
      }

      // Si encontramos el async, insertar el código después
      if (asyncLineIndex > i) {
        // Copiar líneas hasta el async
        for (let j = i + 1; j <= asyncLineIndex; j++) {
          fixedLines.push(lines[j]);
        }
        i = asyncLineIndex;

        // Insertar código que estaba antes del test
        codeBeforeTest.forEach(codeLine => {
          fixedLines.push(codeLine);
        });

        codeBeforeTest = [];
      }
    }
    continue;
  }

  // Si estamos en describe pero NO en test, y hay await page...
  if (inDescribe && !inTest && (trimmed.startsWith('await page.') || trimmed.startsWith('await expect('))) {
    console.log('🔧 Moviendo código al test:', trimmed.substring(0, 50));
    codeBeforeTest.push(line);
    continue;
  }

  fixedLines.push(line);
}

content = fixedLines.join('\n');

// 3.3 Escapar barras en regex toHaveURL
content = content.replace(/toHaveURL\(\/([^)]+)\/\)/g, (match, pattern) => {
  if (pattern.includes('\\/')) return match;
  const escaped = pattern.replace(/\//g, '\\/');
  return `toHaveURL(/${escaped}/)`;
});

// 3.4 Cambiar networkidle a domcontentloaded
content = content.replace(/waitUntil:\s*['"]networkidle['"]/g, "waitUntil: 'domcontentloaded'");

// 3.5 Limpiar líneas vacías excesivas
content = content.replace(/\n{3,}/g, '\n\n');

// 3.6 Remover espacios al final
content = content.replace(/[ \t]+$/gm, '');

// 3.7 Asegurar newline final
if (!content.endsWith('\n')) {
  content += '\n';
}

// 3.8 Fix método inexistente toHaveCountGreaterThan
content = content.replace(
  /await\s+expect\(([^)]+)\)\.toHaveCountGreaterThan\((\d+)\)/g,
  'expect(await $1.count()).toBeGreaterThan($2)'
);

// 3.9 Fix selectores incorrectos en detalle
content = content.replace(/page\.locator\('h2\.name'\)/g, "page.locator('.product-content h2')");
content = content.replace(/page\.locator\('h3\.price-container'\)/g, "page.locator('.product-content h3')");

// 3.10 Fix selector ambiguo en Place Order
content = content.replace(
  /await page\.locator\('#orderModal button'\)\.click\(\);/g,
  "await page.locator('.sweet-alert button.confirm').click();"
);

// 3.11 Fix: Typo en selector #contcont → #tbodyid
content = content.replace(/#contcont/g, '#tbodyid');

// 3.12 Fix: Username único con Date.now()
content = content.replace(
  /fill\(['"]testuser['"]\)/g,
  "fill(`testuser${Date.now()}`)"
);

// 3.13 Fix: Selector ambiguo button.close → específico por modal
content = content.replace(
  /page\.locator\('button\.close'\)/g,
  "page.locator('#videoModal button.close')"
);

// 3.14 Home: usar #tbodyid como contenedor principal, no '.container .row'
content = content.replace(
  /page\.locator\('\.container \.row'\)/g,
  "page.locator('#tbodyid')"
);

// 3.15 Desambiguar expect sobre listas de productos (#tbodyid .card)
content = content.replace(
  /await expect\(page\.locator\('#tbodyid \.card'\)\)\.toBeVisible\(\);/g,
  "await expect(page.locator('#tbodyid .card').first()).toBeVisible();"
);

// 3.16 Asegurar visibilidad de Add to cart antes de click
content = content.replace(
  /(\s*)page\.once\('dialog',([\s\S]*?)\);\n\1await page\.getByRole\('link', { name: 'Add to cart', exact: true }\)\.click\(\);/g,
  "$1const addToCartBtn = page.getByRole('link', { name: 'Add to cart', exact: true });\n" +
    "$1await expect(addToCartBtn).toBeVisible();\n\n" +
    "$1page.once('dialog',$2);\n" +
    "$1await addToCartBtn.click();"
);

// 3.17 Normalizar selectores de paginación Next / Previous
content = content.replace(/button\[onclick="nextPage\(\)"\]/g, '#next2');
content = content.replace(/button\[onclick="prevPage\(\)"\]/g, '#prev2');

// 3.18 Click en tarjeta de producto: usar el <a> interno para navegar al detalle
content = content.replace(
  /await page\.locator\('#tbodyid \.card'\)\.first\(\)\.click\(\);/g,
  "await page.locator('#tbodyid .card').first().locator('a').first().click();"
);


console.log('✅ Fixes aplicados');

// ========================================
// 4. VALIDACIÓN BÁSICA
// ========================================

const hasImport = content.includes('import');
const hasDescribe = content.includes('test.describe');
const hasTest = content.includes('async ({ page })');

if (!hasImport || !hasDescribe || !hasTest) {
  console.log('⚠️ Estructura inválida');
}

// ========================================
// 5. RETORNAR
// ========================================

return {
  json: {
    ...inputData,
    fileName: fileName,
    fileContent: content
  }
};

const prompts = {};

for (const item of items) {
  const fileName = item.json.fileName || item.json['File Name'];

  if (!item.binary || !item.binary.data) continue;

  const bin = item.binary.data;
  const buff = Buffer.from(bin.data, 'base64');
  const text = buff.toString('utf8');

  if (fileName === 'generator-prompt.md') {
    prompts.generatorPrompt = text;
  } else if (fileName === 'healer-prompt.md') {
    prompts.healerPrompt = text;
  } else if (fileName === 'planner-prompt.md') {
    prompts.plannerPrompt = text;
  }
}

return [
  {
    json: prompts,
  },
];

// === Code post-generador ===
// Toma: output, __site, __idx, __title
// Devuelve: { fileName, fileContent, scenarioIndex, scenarioName }

function stripFences(s='') {
  return String(s)
    .replace(/^\s*```(?:json|typescript)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}
function slugify(s='') {
  return String(s)
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase().replace(/[^a-z0-9]+/g,'-')
    .replace(/^-+|-+$/g,'');
}
const pad2 = n => String(Math.max(1, Number(n)||1)).padStart(2,'0');

const site = String($json.__site || 'Demoblaze').trim();
const idx  = Number($json.__idx) > 0 ? Number($json.__idx) : 1;
let   title = String($json.__title || '').trim();

let raw = $json.output ?? $json.fileContent ?? '';
raw = stripFences(raw);

// ¿El generador devolvió JSON?
let fileNameFromGen, fileContent = '';
if (/^\s*{/.test(raw)) {
  try {
    const ob = JSON.parse(raw);
    fileNameFromGen = ob.fileName;
    fileContent = ob.fileContent || ob.output || ob.code || '';
  } catch { fileContent = raw; }
} else {
  fileContent = raw;
}

// Si el título sellado es genérico, intenta inferirlo del código
if (!title || /^escenario\s*\d+$/i.test(title)) {
  const m1 = fileContent.match(/Escenario\s*\d+\s*:\s*([^\n]+)/i);
  const m2 = fileContent.match(/test\(\s*['"]\d{2}\s*-\s*([^'"]+)['"]/);
  title = (m1 && m1[1].trim()) || (m2 && m2[1].trim()) || `Escenario ${pad2(idx)}`;
}

// Asegura import en primera línea
if (!/^import\s+\{\s*test\s*,\s*expect\s*\}\s+from\s+['"]@playwright\/test['"]\s*;/.test(fileContent)) {
  fileContent = `import { test, expect } from '@playwright/test';\n` + fileContent.replace(/^\s+/, '');
}

// Asegura comentario segunda línea
const header = `// ${site} – Escenario ${pad2(idx)}: ${title}\n`;
if (!fileContent.includes(header)) {
  fileContent = fileContent.replace(/^(\s*import[^\n]*\n)(?!\/\/)/, `$1${header}`);
}

// Prefijo "NN - " en el título del test
fileContent = fileContent.replace(/test\(\s*(['"])([^'"]+)\1\s*,/, (m,q,t) => {
  const withNum = /^\d{2}\s*-\s*/.test(t) ? t : `${pad2(idx)} - ${t}`;
  return `test(${q}${withNum}${q},`;
});

// Construir filename
function safe(name){ return slugify(String(name||'')); }
const siteSlug  = safe(site);
const titleSlug = safe(title);

let fileName;
if (fileNameFromGen && /\.spec\.ts$/i.test(fileNameFromGen)) {
  // si el LLM ya trajo un nombre válido, úsalo
  fileName = fileNameFromGen;
} else {
  fileName = `${siteSlug}.${pad2(idx)}.${titleSlug}.spec.ts`;
}

return {
  json: {
    fileName,
    fileContent,
    scenarioIndex: idx,
    scenarioName: title
  }
};

/**
 * POST-GENERADOR (robusto con re-inyección)
 * - Toma el código del agente desde $json.output/$json.fileContent (TS o JSON)
 * - Lee __idx y __title directamente de $json (Set previo los re-inyecta)
 * - Si faltan, intenta fallback a $items('Sellar metadatos', 0, $itemIndex)
 * - Construye: demoblaze.NN.<slug>.spec.ts con NN = __idx, título = __title
 */

function stripFences(s='') {
  return String(s)
    .replace(/^\s*```(?:json|typescript|ts)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}
function slugify(s='') {
  return String(s)
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase().replace(/[^a-z0-9]+/g,'-')
    .replace(/^-+|-+$/g,'');
}
const pad2 = n => String(Math.max(1, Number(n)||1)).padStart(2,'0');

// 0) Prioridad: leer metadatos re-inyectados por el SET
let site  = String($json.__site || $json.siteName || 'Demoblaze').trim();
let idx   = Number($json.__idx);
let title = String($json.__title || '').trim();

// 0b) Fallback: si faltan, intentar desde Sellar metadatos
if (!Number.isFinite(idx) || idx <= 0 || !title) {
  try {
    const it = $items('Sellar metadatos', 0, $itemIndex);
    if (it && it.json) {
      if (!Number.isFinite(idx) || idx <= 0) idx = Number(it.json.__idx);
      if (!title) title = String(it.json.__title || '').trim();
      if (!site) site = String(it.json.__site || 'Demoblaze').trim();
    }
  } catch {}
}
// 0c) Último recurso
if (!Number.isFinite(idx) || idx <= 0) idx = (typeof $itemIndex==='number') ? $itemIndex+1 : 1;
if (!title) title = `Escenario ${pad2(idx)}`;

// 1) Código del agente (TS directo o JSON con fileContent)
let raw = $json.output ?? $json.fileContent ?? '';
raw = stripFences(raw);

let fileContent = '';
if (/^\s*{/.test(raw)) {
  try {
    const o = JSON.parse(raw);
    fileContent = o.fileContent ?? o.output ?? o.code ?? '';
  } catch {
    fileContent = raw;
  }
} else {
  fileContent = raw;
}
fileContent = stripFences(fileContent);

// 2) Si el título es genérico, intentar inferir desde el código
if (!title || /^escenario\s*\d+$/i.test(title)) {
  const m1 = fileContent.match(/Escenario\s*\d+\s*:\s*([^\n]+)/i);
  const m2 = fileContent.match(/test\(\s*(['"])\d{2}\s*-\s*([^'"]+)\1/);
  title = (m1 && m1[1].trim()) || (m2 && m2[2].trim()) || `Escenario ${pad2(idx)}`;
}

// 3) Asegurar import + comentario + "NN - "
if (!/^import\s+\{\s*test\s*,\s*expect\s*\}\s+from\s+['"]@playwright\/test['"]\s*;/.test(fileContent)) {
  fileContent = `import { test, expect } from '@playwright/test';\n` + fileContent.replace(/^\s+/, '');
}
const header = `// ${site} – Escenario ${pad2(idx)}: ${title}\n`;
if (!fileContent.includes(header)) {
  fileContent = fileContent.replace(/^(\s*import[^\n]*\n)(?!\/\/)/, `$1${header}`);
}
fileContent = fileContent.replace(/test\(\s*(['"])([^'"]+)\1\s*,/, (m,q,t) => {
  const withNum = /^\d{2}\s*-\s*/.test(t) ? t : `${pad2(idx)} - ${t}`;
  return `test(${q}${withNum}${q},`;
});

// 4) Nombre de archivo con nuestros metadatos
const siteSlug  = slugify(site);
const titleSlug = slugify(title);
const fileName  = `${siteSlug}.${pad2(idx)}.${titleSlug}.spec.ts`;

return {
  json: {
    fileName,
    fileContent,
    scenarioIndex: idx,
    scenarioName: title
  }
};

/**
 * n8n Code node (JavaScript) — RUN ONCE PER ITEM
 * Sanea un (1) archivo por ejecución y devuelve UN solo objeto {fileName,fileContent}.
 * - Prioriza extraer {fileName,fileContent} desde JSON incrustado (aunque haya “basura” alrededor).
 * - Si no hay JSON, usa el código plano.
 * - Aplica parches Playwright (imports, describe/test, goto, modales Contact/About/Order/Login/Signup, diálogos, SweetAlert, URLs).
 * - Asegura .spec.ts y evita items vacíos (placeholder).
 * - ENDURECIDO: elimina/convierte cualquier selector con `ref=...` (engine y atributos) a `getByRole(...)`.
 */

const j = $json;

// ---------- utils básicos ----------
const toSlug = (s) =>
  String(s ?? '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[“”"’']/g, '')
    .replace(/[^a-z0-9\s-]/g, ' ')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');

const pad2 = (n) => String(Number(n || 1)).padStart(2, '0');

function stripCodeFences(s) {
  return String(s ?? '')
    .replace(/^\s*```(?:json|typescript|ts|javascript|js)?\s*/i, '')
    .replace(/\s*```$/,'')
    .trim();
}
function escapeRegExp(s){ return String(s ?? '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

function coalesce(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null) {
      const sv = typeof v === 'string' ? v : (typeof v === 'object' ? JSON.stringify(v) : String(v));
      if (String(sv).trim() !== '') return v;
    }
  }
  return '';
}

function ensureTsFileName(name, fallback) {
  let out = String(name ?? '').trim();
  if (!out) out = fallback;
  if (!/\.(ts|tsx|js)$/i.test(out)) {
    if (!out.endsWith('.spec')) out += '.spec';
    out += '.ts';
  }
  out = out.replace(/[\\\/]+/g, '_').replace(/\s+/g, '-');
  return out;
}

// ---------- extractor robusto de JSON incrustado ----------
function extractJsonEnvelope(big) {
  const s = String(big ?? '');
  // Intento 1: string completo es JSON
  try {
    const obj = JSON.parse(s);
    if (obj && typeof obj === 'object' && (obj.fileContent || obj.content || obj.text || obj.code)) {
      return {
        fileName: obj.fileName || obj.filename || undefined,
        fileContent: String(obj.fileContent ?? obj.content ?? obj.text ?? obj.code ?? ''),
      };
    }
  } catch {}

  // Intento 2: buscar bloque con "fileContent"
  const idxFirstBrace = s.indexOf('{');
  const idxLastBrace  = s.lastIndexOf('}');
  if (idxFirstBrace !== -1 && idxLastBrace !== -1 && idxLastBrace > idxFirstBrace) {
    const window = s.slice(idxFirstBrace, idxLastBrace + 1);
    const candidates = [];
    const re = /\{[\s\S]*?"fileContent"\s*:\s*("[\s\S]*?"|null|true|false|\d+|\{[\s\S]*?\}|\[[\s\S]*?\])[\s\S]*?\}/g;
    let m;
    while ((m = re.exec(window)) !== null) candidates.push(m[0]);
    for (let i = candidates.length - 1; i >= 0; i--) {
      try {
        const obj = JSON.parse(candidates[i]);
        if (obj && typeof obj === 'object' && (obj.fileContent || obj.content || obj.text || obj.code)) {
          return {
            fileName: obj.fileName || obj.filename || undefined,
            fileContent: String(obj.fileContent ?? obj.content ?? obj.text ?? obj.code ?? ''),
          };
        }
      } catch {}
    }
  }
  return null;
}

