// ROBUSTO: asegura async en TODO callback de test(...)
function ensureAsyncTestCallbacks(code) {
  // 1) Arrow sin async: test('...', ({ ... }) => { ... })
  code = code.replace(
    /(test(?:\.(?:only|skip|fixme|fail))?\(\s*(['"`].*?['"`])\s*,\s*)\(\s*([^)]*)\)\s*=>\s*\{/gs,
