  // 2) Forma function: test('...', function(...) { ... })
  code = code.replace(
    /(test(?:\.(?:only|skip|fixme|fail))?\(\s*(['"`].*?['"`])\s*,\s*)function\s*\(\s*([^)]*)\s*\)\s*\{/gs,
    "$1async function ($3) {"
