// ---------- NUEVAS CORRECCIONES PUNTUALES (sin cambiar tu estructura) ----------
function cleanJsonArtifacts(code) {
  // Si el archivo quedó como un objeto JSON con "fileName"/"fileContent", extrae el contenido
  if (/^\s*\{\s*"fileName"\s*:\s*".*?",\s*"fileContent"\s*:\s*"/s.test(code)) {
    try {
      const parsed = JSON.parse(code);
      if (parsed && typeof parsed === 'object' && typeof parsed.fileContent === 'string') {
        return String(parsed.fileContent);
      }
    } catch {}
  }
  return code;
}

function enforceCleanHomeUrlRegex(code) {
  // 1) Arregla variantes con slashes sin escapar (causan el \uXXXX)
  code = code.replace(
    /toHaveURL\(\s*\/https:\/\/demoblaze\.com\/?\s*\/\s*\)/g,
    "toHaveURL(/https:\\/\\/demoblaze\\.com\\/?/)"
  );

  // 2) Arregla variantes con doble escape (https\\/\\/)
  code = code.replace(
    /toHaveURL\(\s*\/https:\\\\\/\\\\\/demoblaze\\.com\\\\\/\?\//g,
    "toHaveURL(/https:\\/\\/demoblaze\\.com\\/?/)"
  );

  // 3) Variante sin el opcional final
  code = code.replace(
    /toHaveURL\(\s*\/https:\\\/\\\/demoblaze\.com\/\s*\/\s*\)/g,
    "toHaveURL(/https:\\/\\/demoblaze\\.com\\/?/)"
  );

  // 4) Cualquier resto que contenga "demoblaze.com" en toHaveURL con regex literal:
  //    si aún no tiene los slashes escapados, normaliza.
  code = code.replace(
    /toHaveURL\(\s*\/(https:\/\/)?demoblaze\.com(\/\?)?\/\s*\)/g,
    "toHaveURL(/https:\\/\\/demoblaze\\.com\\/?/)"
  );

  return code;
}


function fixBrokenAwaits(code) {
  // Elimina líneas con "await ).algo(...)" o "await );"
  code = code.replace(/^\s*await\s*\)\s*\.[a-zA-Z_]\w*\s*\([^)]*\)\s*;?\s*$/gm, `// FIX removed broken await chain`);
  code = code.replace(/^\s*await\s*\);\s*$/gm, `// FIX removed dangling await`);
  return code;
}

// NUEVO: corta cualquier cadena colgante que comience con ").metodo(...)" o una ")" suelta
function fixDanglingChains(code) {
  // 1) ").toBeVisible();" / ").not.toBeVisible();" / ").click();" etc.
  code = code.replace(/^\s*\)\s*\.[a-zA-Z_]\w*(?:\.[a-zA-Z_]\w*)*\s*\([^)]*\)\s*;?\s*$/gm, `// FIX removed dangling chain`);
  // 2) ")" suelta o ");" suelta en su propia línea
  code = code.replace(/^\s*\)\s*;?\s*$/gm, `// FIX removed stray close`);
  // 3) Dobles espacios/ saltos múltiples tras limpieza
  code = code.replace(/\n{3,}/g, '\n\n');
  return code;
}

/** NUEVO: evita cierre prematuro del bloque de test cuando vienen awaits críticos después */
function preventPrematureCloseAroundCriticalAwaits(code) {
  const critical = [
    "getByRole('button', { name: 'Purchase' }).click()",
    "locator('h2.sa-title')",
    "getByRole('button', { name: 'OK' }).click()",
    "getByRole('button', { name: 'Send message' }).click()",
  ];
  const lines = code.split('\n');
  for (let i = 0; i < lines.length - 1; i++) {
    if (/^\s*\}\);\s*$/.test(lines[i])) {
      const lookahead = lines.slice(i + 1, i + 6).join('\n');
      if (critical.some(sig => lookahead.includes(sig))) {
        lines[i] = '// FIX removed premature close of test block';
      }
    }
  }
  return lines.join('\n');
}

// NUEVO: si hay más '}' que '{', recorta cierres sueltos al final
function trimExcessClosingBraces(code) {
  let opens = (code.match(/{/g) || []).length;
  let closes = (code.match(/}/g) || []).length;
  if (closes > opens) {
    const lines = code.split('\n');
    for (let i = lines.length - 1; i >= 0 && closes > opens; i--) {
      if (/^\s*\}\s*;?\s*$/.test(lines[i])) {
        lines[i] = '// FIX trimmed extra closing brace';
        closes--;
      }
    }
    return lines.join('\n');
  }
  return code;
}

function ensureBalancedParentheses(code) {
  const open = (code.match(/\(/g) || []).length;
  const close = (code.match(/\)/g) || []).length;
  if (close < open) code += ')'.repeat(open - close);
  return code;
}

function ensureAsyncAtRootIfAwaitExists(code) {
  if (code.includes('await ') && !code.includes('async ({ page })')) {
    code = code.replace(/test\((['"].*?['"])\s*,\s*\(\s*\{\s*page\s*\}\s*\)\s*=>/s,
      'test($1, async ({ page }) =>');
  }
  return code;
}


function balanceBraces(code) {
  const opens = (code.match(/{/g) || []).length;
  const closes = (code.match(/}/g) || []).length;
  if (opens > closes) {
    return code + '\n'.repeat(Math.min(3, opens - closes)) + '}'.repeat(opens - closes) + '\n';
  }
  return code;
}

// --- DEDUPE: si una const/let/var se declara 2+ veces, la 2da se convierte en asignación ---
function fixDuplicateIdentifiers(code) {
  const lines = code.split('\n');
  const declared = new Set();
  const declRE = /^\s*(const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*/;

  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(declRE);
    if (!m) continue;
    const kind = m[1];
    const name = m[2];

    if (declared.has(name)) {
      // Si ya existe, convierto "const name =" → "name =" (asignación simple)
      lines[i] = lines[i].replace(declRE, `${name} = `);
    } else {
      declared.add(name);
    }
  }
  return lines.join('\n');
}

// --- INLINER: elimina variables intermedias duplicables `const x = expr; await expect(x)` → `await expect(expr)`
function inlineImmediateExpectTargets(code) {
  // Caso: const v = <expr>;
  //       await expect(v)...
  // Reemplaza por: await expect(<expr>) y elimina la const si no se usa más en la misma línea
  return code.replace(
    /(?:^|\n)\s*const\s+([A-Za-z_$][\w$]*)\s*=\s*(.+?)\s*;\s*\n\s*await\s+expect\(\s*\1\s*\)/gs,
    (m, vname, rhs) => `\nawait expect(${rhs.trim()})`
  );
}

// --- Recorte fuerte de colgantes de cierre al final (EOF): "}", ")", ");" sueltos ---
function trimTrailingDanglingClosers(code) {
  const lines = code.split('\n');
  // Elimina líneas finales que sean solo "}" o ")" o ");"
  while (lines.length && /^\s*(\}|\)|\);\s*)\s*$/.test(lines[lines.length - 1])) {
    lines[lines.length - 1] = '// FIX trimmed trailing closer';
    // Si quedan sólo comentarios FIX al final, corta comentarios repetidos
    if (/^\s*\/\/ FIX/.test(lines[lines.length - 1]) && lines.length > 1 && /^\s*\/\/ FIX/.test(lines[lines.length - 2])) {
      lines.pop();
    } else {
      break;
    }
  }
  return lines.join('\n');
}

// --- Balanceo adicional de paréntesis + recorte de ")\n" finales repetidos ---
function ensureBalancedParensAndTrim(code) {
  const open = (code.match(/\(/g) || []).length;
  const close = (code.match(/\)/g) || []).length;
  if (open > close) {
    code += ')'.repeat(open - close);
  }
  // Si hay más ")" que "(", recorta ")" sueltos desde EOF
  if (close > open) {
    const diff = close - open;
    let cut = diff;
    const lines = code.split('\n');
    for (let i = lines.length - 1; i >= 0 && cut > 0; i--) {
      if (/^\s*\)\s*;?\s*$/.test(lines[i])) {
        lines[i] = '// FIX trimmed stray )';
        cut--;
      }
    }
    code = lines.join('\n');
  }
  return code;
}

// --- Seguridad: si hay await en el test y el callback no es async, lo forzamos ---
function ensureAsyncAtRootIfAwaitExists(code) {
  if (/\bawait\s+/.test(code) && !/test\(\s*['"`][\s\S]*?['"`]\s*,\s*async\s*\(\s*\{\s*page\s*\}\s*\)\s*=>/s.test(code)) {
    code = code.replace(
      /test\(\s*(['"`].*?['"`])\s*,\s*\(\s*\{\s*page\s*\}\s*\)\s*=>/s,
      'test($1, async ({ page }) =>'
    );
  }
  return code;
}

// --- LIMPIADOR DE PUNTOS SUELTOS Y TOKENS HUÉRFANOS ---
function removeDanglingDotsAndBrokenTokens(code) {
  const lines = code.split('\n');
  for (let i = 0; i < lines.length; i++) {
    // Línea que contiene solo un punto o símbolos sueltos
    if (/^\s*\.\s*$/.test(lines[i])) {
      lines[i] = '// FIX removed stray dot';
    }
    // Corrige ".;" o ".," o ".)"
    lines[i] = lines[i]
      .replace(/(\s+)\.\s*;?/g, '$1')   // elimina punto solitario antes de ;
      .replace(/(\s+)\.\s*,/g, '$1')   // elimina punto antes de coma
      .replace(/\.\s*\)/g, ')')        // elimina punto antes de cierre )
      .replace(/\)\s*\./g, ')');       // elimina punto después de )
  }
  return lines.join('\n');
}

// ---------- metadatos ----------
const site = toSlug(j.__site ?? j.siteName ?? 'demoblaze');
const idx = pad2(j.__idx ?? j.scenarioIndex ?? 1);
const scenarioName = String(j.__title ?? j.scenarioName ?? `Escenario ${idx}`).trim() || `Escenario ${idx}`;
const defaultSafeName = `${site}.${idx}.${toSlug(scenarioName)}.spec.ts`;

// ---------- entrada robusta ----------
let providedFileName =
  coalesce(j.fileName, j.filename, j.data?.fileName, j.result?.fileName,
           j.generated?.fileName, j.payload?.fileName, j.body?.fileName, j.response?.fileName);

let big =
  coalesce(j.output, j.text, j.fileContent, j.content, j.code,
           j.data?.fileContent, j.result?.fileContent, j.generated?.fileContent,
           j.payload?.fileContent, j.body?.fileContent, j.response?.fileContent);

big = stripCodeFences(String(big));
let envelope = extractJsonEnvelope(big);

if (!envelope) {
  if (j.fileContent || j.content || j.text || j.code) {
    envelope = {
      fileName: j.fileName || j.filename,
      fileContent: String(j.fileContent ?? j.content ?? j.text ?? j.code ?? ''),
    };
  }
}

const finalName = ensureTsFileName((envelope && envelope.fileName) || providedFileName, defaultSafeName);
let code = String((envelope && envelope.fileContent) || big || '').replace(/^\uFEFF/, '').trim();

if (!code) {
  code = `import { test, expect } from '@playwright/test';
// ${finalName} generado automáticamente por el sanitizador porque la fuente no trajo contenido.
// Ajusta el generador para proveer 'fileContent'.
test('placeholder - contenido vacío', async () => {
  expect(1).toBe(1);
});
`;
}

// === APLICAR CORRECCIONES PRE-SANITIZADO DURO ===
code = cleanJsonArtifacts(code);
// Quita líneas que solo contienen un punto (causa "Unexpected token .")
code = code.replace(/^\s*\.\s*$/gm, '');
code = fixBrokenAwaits(code);
code = fixDanglingChains(code);
// Evita cierres prematuros antes de awaits críticos (Purchase / OK / Send message / SweetAlert)
code = preventPrematureCloseAroundCriticalAwaits(code);
// Si vienen más '}' que '{', recorta desde el final
code = trimExcessClosingBraces(code);
// Balancea (si aún faltan cierres)
code = balanceBraces(code);

// ---------- parches Playwright ----------
// Imports + encabezado + nombres
code = ensureImport(code);
const siteTitle = site.charAt(0).toUpperCase() + site.slice(1);
code = upsertHeaderComment(code, siteTitle, idx, scenarioName);
code = normalizeDescribeAndTest(code, siteTitle, idx, scenarioName);
code = ensureAsyncTestCallbacks(code);

// Navegación estable
({ code } = fixExistingGotoNetworkIdle(code));
code = ensureGotoAtStart(code);

// Limpiezas/fixes específicos que te estaban fallando
code = purgeRefEngineEverywhere(code, scenarioName); // *** NUEVO: mata y sustituye todo `ref=...`
code = fixWeirdLinkLocatorSyntax(code);              // corrige locator('link "Laptops" [ref=e28]')
code = fixProductNameStrictAssertions(code);         // usa roles para productos
code = stabilizeMonitorsCategoryCheck(code);         // Monitors sin arrays

// Otros normalizadores
code = normalizeAddToCartRole(code);
code = removeWaitForTimeout(code);
code = normalizeCartUrlAndBasics(code);
code = normalizePlaceOrderHeading(code);
code = normalizeContact(code);
code = hardenAboutUsModal(code);
code = ensureDialogHandlers(code);
